package com.school.management.controller;
import com.school.management.entity.AppUser; import com.school.management.repository.AppUserRepository; import jakarta.validation.Valid; import jakarta.validation.constraints.Email; import jakarta.validation.constraints.NotBlank; import jakarta.validation.constraints.Size; import org.springframework.http.*; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/users") @PreAuthorize("hasRole('ADMIN')") public class UserAdminController {
 private final AppUserRepository users; private final PasswordEncoder encoder;
 public UserAdminController(AppUserRepository users,PasswordEncoder encoder){this.users=users;this.encoder=encoder;}
 public record CreateUserRequest(@Email @NotBlank String email,@NotBlank @Size(min=8,max=100) String password,@NotBlank String fullName,String role){}
 @GetMapping public List<Map<String,Object>> list(){return users.findAll().stream().map(u->Map.<String,Object>of("id",u.getId(),"email",u.getEmail(),"fullName",u.getFullName(),"role",u.getRole(),"enabled",u.isEnabled())).toList();}
 @PostMapping public ResponseEntity<?> create(@Valid @RequestBody CreateUserRequest r){String email=r.email().trim().toLowerCase(Locale.ROOT);if(users.existsByEmailIgnoreCase(email))return ResponseEntity.badRequest().body(Map.of("message","Email is already registered"));String role=r.role()==null?"TEACHER":r.role().trim().toUpperCase(Locale.ROOT);if(!Set.of("ADMIN","REGISTRAR","TEACHER","ACCOUNTANT").contains(role))return ResponseEntity.badRequest().body(Map.of("message","Role must be ADMIN, REGISTRAR, TEACHER, or ACCOUNTANT"));AppUser u=new AppUser();u.setEmail(email);u.setFullName(r.fullName().trim());u.setPasswordHash(encoder.encode(r.password()));u.setRole(role);u.setEnabled(true);AppUser saved=users.save(u);return ResponseEntity.status(HttpStatus.CREATED).body(Map.of("id",saved.getId(),"email",saved.getEmail(),"fullName",saved.getFullName(),"role",saved.getRole(),"enabled",saved.isEnabled()));}
 @PatchMapping("/{id}/role") public ResponseEntity<?> changeRole(@PathVariable Long id,@RequestBody Map<String,String> body){AppUser u=users.findById(id).orElseThrow(()->new NoSuchElementException("User not found"));String role=body.getOrDefault("role","").toUpperCase(Locale.ROOT);if(!Set.of("ADMIN","REGISTRAR","TEACHER","ACCOUNTANT").contains(role))throw new IllegalArgumentException("Invalid role");u.setRole(role);users.save(u);return ResponseEntity.ok(Map.of("id",u.getId(),"email",u.getEmail(),"role",u.getRole()));}
}
